      source: 'local-fallback',
      reason: result.error,
      model: null,
      context: {
        adapter_version: structuredContext.adapter_version,
        transcript_chunks: structuredContext.transcript.chunks.length,
        transcript_truncated: structuredContext.transcript.truncated
      },
    };
  }

