675	  const graphItems = graphVerification || [];
676	  const graphVerified = graphItems.filter(item => item.status === 'VERIFIED').length;
677	  const generatedAt = new Date().toISOString();
678	  const evidenceClass = analysis?.provenance?.evidence_class || 'REAL ENTIRE EVIDENCE';
679	  const aiLabel = options.analysisSource === 'databricks'
680	    ? `AI GENERATED BY DATABRICKS (${options.model || DATABRICKS_MODEL})`
681	    : `LOCAL FALLBACK ANALYSIS (${options.fallbackReason || 'Databricks unavailable or response could not be parsed'})`;
682	
683	  const lines = [
684	    '# Code Archaeologist Intelligence Report',
685	    '',
686	    `Checkpoint: ${checkpointId}`,
687	    `Repository: ${repoPath}`,
688	    `Generated: ${generatedAt}`,
689	    '',
690	    '## Provenance',
691	    `- ${evidenceClass}: Entire checkpoint/session context`,
692	    `- ${aiLabel}`,
693	    `- GRAPH VERIFIED: ${graphVerified}/${graphItems.length} findings have Entire Graph VERIFIED status`,
694	    '',
695	    '## Reconstructed Intent',
696	    analysis?.original_intent || analysis?.intent || 'Intent unavailable',
697	    '',
698	    '## Requirements Summary',
