703	    '',
704	    ...requirements.map(item => formatFinding(item, 'UNVERIFIED')),
705	    '',
706	    '## Completed Work',
707	    ...(completed.length ? completed.map(item => formatFinding(item)) : ['- None identified']),
708	    '',
709	    '## Partially Completed Or Missing Work',
710	    ...(partial.length ? partial.map(item => formatFinding(item, 'PARTIAL')) : []),
711	    ...(unfinished.length ? unfinished.map(item => formatFinding(item, 'MISSING')) : ['- None identified']),
712	    '',
713	    '## Decisions And Assumptions',
714	    ...(decisions.length ? decisions.map(item => formatFinding(item)) : ['- No decisions identified']),
715	    ...(assumptions.length ? assumptions.map(item => `- [${item.verification_status || 'UNVERIFIED'}] ${item.description} (risk ${item.risk_level || 'MEDIUM'}; confidence ${confidencePercent(item)}; source: ${item.source_checkpoint_evidence || item.source || item.evidence || 'checkpoint evidence unavailable'})`) : ['- No assumptions identified']),
716	    '',
717	    '## Risks',
718	    ...(risks.length ? risks.map(item => `- [${item.severity || 'MEDIUM'}] ${item.description} (confidence ${confidencePercent(item)}; source: ${item.source_checkpoint_evidence || item.evidence || 'checkpoint evidence unavailable'})`) : ['- No risks identified']),
719	    '',
720	    '## Entire Graph Evidence',
721	    ...(graphItems.length ? graphItems.map(item => {
722	      const matches = item.evidence?.top_matches?.length
723	        ? item.evidence.top_matches.map(match => `${match.file}:${match.line || '?'}`).join(', ')
724	        : 'no matches';
725	      return `- [${item.status}] ${item.claim} | query: ${item.query} | ${matches}`;
726	    }) : ['- Graph verification was not run or produced no evidence']),
727	    '',
728	    '## Recommended Next Actions',
729	    ...(nextSteps.length ? nextSteps.map(item => `- [${item.priority || 'MEDIUM'}] ${item.description}`) : ['- Review graph-unverified findings before release'])
730	  ];
731	
732	  return lines.join('\n');
733	}
