336	  const safeSystemPrompt = redactSensitiveText(systemPrompt);
337	  const safeUserPrompt = redactSensitiveText(userPrompt);
338	
339	  const useResponsesApi = DATABRICKS_API_MODE === 'responses';
340	
341	  // Mode 1: Databricks AI Gateway / MLflow Chat Completions for system.ai model services.
342	  if (DATABRICKS_MODEL.startsWith('system.ai') && !useResponsesApi) {
343	    const chatUrl = `${cleanHost}/ai-gateway/mlflow/v1/chat/completions`;
344	    try {
345	      const response = await fetch(chatUrl, {
346	        method: 'POST',
347	        headers: {
348	          'Authorization': `Bearer ${DATABRICKS_TOKEN}`,
349	          'Content-Type': 'application/json',
350	        },
351	        body: JSON.stringify({
352	          model: DATABRICKS_MODEL,
353	          messages: [
354	            { role: 'system', content: safeSystemPrompt },
355	            { role: 'user', content: safeUserPrompt },
