357	          max_tokens: options.maxTokens || 4096,
358	          temperature: options.temperature || 0,
359	        })
360	      });
361	
362	      if (!response.ok) {
363	        const errText = await response.text();
364	        return { success: false, error: `Databricks AI Gateway ${response.status}: ${errText}` };
