366	
367	      const result = await response.json();
368	      const content = extractMessageText(result.choices?.[0]?.message?.content);
369	      return {
370	        success: true,
371	        data: content,
372	        model: result.model || DATABRICKS_MODEL,
373	        usage: result.usage || null
374	      };
375	    } catch (err) {
376	      return { success: false, error: `AI Gateway error: ${err.message}` };
377	    }
378	  }
